arguments.argument:
if obj_draw.click_number>-1
{

load=get_directory_alt("저장폴더를 선택해주세요", "")

if load!=""
{
sk_dlrc_load(global.fodre+string(obj_draw.click_number)+".dlrc", "+|+")

for(t=1; t!=dlrc_max_number; t+=1)
{
sk_dlrc_extract(global.fodre+string(obj_draw.click_number)+".dlrc", load+"\", t)
}
}

}
